using System;using System.Collections.Generic;using System.Linq;using System.Text.Json;using Microsoft.Xna.Framework;using StardewModdingAPI;using StardewModdingAPI.Events;using StardewValley;using StardewValley.Buildings;using StardewValley.Characters;using StardewValley.Menus;using Tile=BetterStardewValley.HorseRules.Tile;
namespace BetterStardewValley;
internal static partial class Program {
 static int checks;static readonly List<string> scenarios=new();static string root="";
 static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
 static void Case(string name,Action body){body();scenarios.Add(name);}
 sealed class World {
  internal IModHelper Helper;internal HorseFeature Mod;internal ModConfig Config;internal GameLocation Farm,Town;internal Farmer A,B;internal Horse HA,HB;internal Stable SA,SB;
  internal World(){Context.IsMainPlayer=true;Context.IsSplitScreen=false;Context.IsWorldReady=true;Context.IsPlayerFree=true;Context.ScreenId=0;Game1.IsMultiplayer=true;Game1.eventUp=false;Game1.activeClickableMenu=null;Game1.Trace.Clear();Game1.Warps.Clear();Game1.Offline.Clear();Farm=new(){Name="Farm"};Town=new(){Name="Town"};Game1.Locations=new(){Farm,Town};A=new(){UniqueMultiplayerID=101,Name="A",Position=new(25*64,25*64),currentLocation=Farm};B=new(){UniqueMultiplayerID=202,Name="B",Position=new(45*64,25*64),currentLocation=Farm,IsLocalPlayer=false};Game1.Players=new(){A,B};Game1.player=Game1.MasterPlayer=A;Game1.currentLocation=Farm;Game1.viewport=new(1280,1360,640,480);Farm.farmers.AddRange(new[]{A,B});SA=new(){Parent=Farm};SB=new(){Parent=Farm};SA.owner.Value=101;SB.owner.Value=202;Farm.buildings.AddRange(new[]{SA,SB});HA=new(){HorseId=SA.HorseId,Name="Maple",Position=new(8*64,25*64),currentLocation=Farm};HB=new(){HorseId=SB.HorseId,Name="Hazel",Position=new(62*64,25*64),currentLocation=Farm};HA.ownerId.Value=101;HB.ownerId.Value=202;Farm.characters.AddRange(new[]{HA,HB});Config=new();Helper=new(){DirectoryPath=root};Mod=new(Helper,new(),"Eddie.BetterStardewValley",Config);Views();}
  internal void Views(){Mod.InspectView(A,(int)A.Position.X-320,(int)A.Position.Y-240);Mod.InspectView(B,(int)B.Position.X-320,(int)B.Position.Y-240);}
  internal HorseRequest Request(Farmer who,Horse horse,string action="Call",string name="")=>new(){Id=Guid.NewGuid().ToString("N"),Actor=who.UniqueMultiplayerID,Horse=horse.HorseId.ToString("N"),Location=who.currentLocation.Name,Action=action,Name=name,View=new(){Actor=who.UniqueMultiplayerID,Location=who.currentLocation.Name,X=(int)who.Position.X-320,Y=(int)who.Position.Y-240,Width=640,Height=480}};
  internal void Cross(){Farm.farmers.Remove(A);Town.farmers.Add(A);A.currentLocation=Town;Game1.currentLocation=Town;Views();}
  internal void Run(int n=600){for(int i=0;i<n&&Mod.Running>0;i++){Views();Mod.MovementStep();Check(HA.rider==null&&HB.rider==null,"No fabricated rider during movement");}}
 }
 static void Main(string[] args){root=args[0];
  Case("native owner precedence and stable-name isolation",()=>{var w=new World();w.HA.ownerId.Value=202;HorseFeature.Recovery(w.SA);Check(w.SA.owner.Value==202,"horse owner recovered before stable overwrites");w.HA.ownerId.Value=0;w.SA.owner.Value=101;HorseFeature.Recovery(w.SA);Check(w.HA.ownerId.Value==101,"stable fallback");w.SA.modData[HorseFeature.PersistentNameKey]="Maple";w.A.horseName.Value="Another horse";w.SA.updateHorseOwnership();HorseFeature.Recovery(w.SA);Check(w.HA.Name=="Maple","per-stable name survives vanilla player-wide rewrite");});
  Case("two owners and non-owner mount rejection including offline owner",()=>{var w=new World();Check(HorseFeature.ActionCheck(w.HA,w.A),"A rides A");Check(!HorseFeature.ActionCheck(w.HA,w.B),"B blocked from A");Check(HorseFeature.ActionCheck(w.HB,w.B),"B rides B");Check(!HorseFeature.ActionCheck(w.HB,w.A),"A blocked from B");Game1.Offline.Add(202);Check(!HorseFeature.ActionCheck(w.HB,w.A),"offline doesn't release ownership");Check(w.HB.ownerId.Value==202&&w.SB.owner.Value==202,"no changed owner");});
  Case("unnamed owned horse uses naming without vanilla ownership reassignment",()=>{var w=new World();w.HA.Name="";Check(!HorseFeature.ActionCheck(w.HA,w.A),"intercept vanilla unnamed claim branch");Check(Game1.activeClickableMenu is NamingMenu,"native style naming dialog");((NamingMenu)Game1.activeClickableMenu!).Callback("Clover");w.HA.Position=w.A.Position+new Vector2(128,0);w.Helper.Events.GameLoop.Tick();Check(w.HA.Name=="Clover"&&w.SA.owner.Value==101&&w.SB.owner.Value==202,"name saved with owners untouched");});
  Case("horse names do not shadow vanilla villager lookups",()=>{var w=new World();w.Farm.characters.Add(new NPC{Name="Robin"});w.HA.Position=w.A.Position+new Vector2(128,0);w.Mod.Handle(w.Request(w.A,w.HA,"Name","Robin"));Check(w.HA.Name=="Robin "&&w.HA.displayName=="Robin","vanilla disambiguation retained");HorseFeature.Recovery(w.SA);Check(w.HA.Name=="Robin ","reload retains internal name separation");});
  Case("legacy claim once on host; second claimant rejected",()=>{var w=new World();w.SA.owner.Value=w.HA.ownerId.Value=0;w.HA.Name="";HorseFeature.Recovery(w.SA);Check(w.SA.owner.Value==0,"not assigned to host");w.HA.Position=w.A.Position+new Vector2(128,0);w.Mod.Handle(w.Request(w.A,w.HA,"Claim","Comet"));Check(w.HA.ownerId.Value==101&&w.SA.owner.Value==101&&w.HA.Name=="Comet","claim transaction native fields");w.B.Position=w.A.Position;w.Mod.Handle(w.Request(w.B,w.HA,"Claim","Stolen"));Check(w.HA.ownerId.Value==101&&w.HA.Name=="Comet","second claim rejected");});
  Case("immediate whistle; H/V/mouse/controller/None and cooldown",()=>{var w=new World();w.Farm.IsOutdoors=false;w.Helper.Events.Input.Raise(SButton.H);Check(Game1.Trace.SequenceEqual(new[]{"Whistle","Message:horse.call.unavailable_location"}),"whistle before location error");w.Helper.Events.Input.Raise(SButton.H);Check(Game1.Trace.Count==2,"cooldown silences repeats");w.Config.CallHorseKey=SButton.V;w.Mod.ResetInput();Game1.Trace.Clear();w.Helper.Events.Input.Raise(SButton.H);Check(Game1.Trace.Count==0,"old H disabled");w.Helper.Events.Input.Raise(SButton.V);Check(Game1.Trace[0]=="Whistle","V enabled");foreach(var b in new[]{SButton.MouseX1,SButton.ControllerA}){w.Mod.ResetInput();w.Config.CallHorseKey=b;Game1.Trace.Clear();w.Helper.Events.Input.Raise(b);Check(Game1.Trace[0]=="Whistle","SMAPI non-keyboard input");}w.Mod.ResetInput();w.Config.CallHorseKey=SButton.None;Game1.Trace.Clear();w.Helper.Events.Input.Raise(SButton.None);w.Helper.Events.Input.Raise(SButton.H);Check(Game1.Trace.Count==0,"None disables binding");});
  Case("supported outdoor names and forbidden indoor/dungeon types",()=>{var w=new World();foreach(string n in new[]{"Farm","Town","Forest","Mountain","Beach","BusStop","Railroad","Desert","IslandWest","IslandSouth","IslandNorth"}){w.Farm.Name=n;Check(HorseFeature.CanCall(w.Farm),n);}foreach(string n in new[]{"FarmHouse","Saloon","Hospital","CommunityCenter","Greenhouse","Shed","AnimalHouse","SeedShop"}){w.Farm.Name=n;w.Farm.IsOutdoors=false;Check(!HorseFeature.CanCall(w.Farm),n);}w.Farm.IsOutdoors=true;foreach(string n in new[]{"UndergroundMine1","UndergroundMine121","SkullCave","VolcanoDungeon0","VolcanoCaldera","BugLand","CustomDungeon"}){w.Farm.Name=n;Check(!HorseFeature.CanCall(w.Farm),n);}w.Farm.Name="Town";w.Farm.currentEvent=new();Check(!HorseFeature.CanCall(w.Farm),"event unsafe");w.Farm.currentEvent=null;w.Farm.Map.Properties["BSVNoHorseCall"]="true";Check(!HorseFeature.CanCall(w.Farm),"map opt-out");});
  Case("mounted/no horse/wrong owner never spawn",()=>{var w=new World();w.A.mount=w.HA;w.HA.rider=w.A;w.Mod.Handle(w.Request(w.A,w.HA));Check(w.Mod.Running==0&&Game1.Warps.Count==0,"mounted unchanged");w.Mod.Handle(w.Request(w.B,w.HA));Check(w.Mod.Running==0,"owner mismatch rejected");w.A.mount=null;w.HA.rider=null;w.Farm.characters.Remove(w.HA);w.Mod.ResetInput();w.Helper.Events.Input.Raise(SButton.H);Check(Game1.Trace.Last()=="Message:horse.call.no_horse"&&w.Farm.characters.Count==1,"no replacement horse");});
  Case("simultaneous independent same-map summons; stable identity",()=>{var w=new World();w.Mod.Handle(w.Request(w.A,w.HA));w.Mod.Handle(w.Request(w.B,w.HB));Check(w.Mod.Running==2,"independent active states");w.Run();Check(w.Mod.Running==0&&Game1.Warps.Count==0,"both run from current position");Check(Vector2.Distance(w.HA.Position,w.A.Position)>=120&&Vector2.Distance(w.HA.Position,w.A.Position)<=330,"A safe parking");Check(Vector2.Distance(w.HB.Position,w.B.Position)>=120&&Vector2.Distance(w.HB.Position,w.B.Position)<=330,"B safe parking");Check(w.SA.getStableHorse()==w.HA&&w.SB.getStableHorse()==w.HB,"same objects and native GUIDs");Check(w.HA.Sprite.CurrentFrame==HorseRules.IdleFrame(w.HA.FacingDirection),"idle restored");});
  Case("cross-location reuses real horse offscreen then runs to caller",()=>{var w=new World();w.Cross();var r=w.Request(w.A,w.HA);w.Mod.Handle(r);w.Mod.MovementStep();Check(Game1.Warps.Count==1&&ReferenceEquals(Game1.Warps[0].Horse,w.HA),"one warp of existing native instance");var pos=Game1.Warps[0].Position;Check(HorseRules.OutsideBand(new((int)pos.X-48,(int)pos.Y-112,192,208),new(r.View.X,r.View.Y,r.View.Width,r.View.Height),2,5),"2-5 tiles beyond actual viewport");Check(Vector2.Distance(pos,w.A.Position)>6*64,"not at destination");w.Run();Check(w.HA.currentLocation==w.Town&&Game1.Locations.Sum(l=>l.characters.OfType<Horse>().Count())==2,"real horse no duplicates");});
  Case("other player's visible source blocks a visible disappearance",()=>{var w=new World();w.Cross();w.B.Position=w.HA.Position+new Vector2(128,0);w.Views();w.Mod.Handle(w.Request(w.A,w.HA));w.Mod.MovementStep();Check(w.Mod.Running==0&&Game1.Warps.Count==0&&w.HA.currentLocation==w.Farm,"no visible teleport");});
  Case("no safe parking leaves horse at source",()=>{var w=new World();w.Cross();w.Town.Obstacles.Add(new((int)w.A.Position.X-6*64,(int)w.A.Position.Y-6*64,13*64,13*64));w.Mod.Handle(w.Request(w.A,w.HA));w.Mod.MovementStep();Check(w.Mod.Running==0&&Game1.Warps.Count==0,"no force-spawn");Check(w.Mod.Last(101)?.Message=="horse.call.no_path","localized failure");});
  Case("collision footprint, water, objects, players, NPCs and missing Back tiles",()=>{var w=new World();var p=new Vector2(10*64,10*64);Check(HorseFeature.CheckSafe(w.Farm,w.HA,p),"clear ground");w.Farm.Water.Add((11,10));Check(!HorseFeature.CheckSafe(w.Farm,w.HA,p),"water under wide right hoof");w.Farm.Water.Clear();w.Farm.Obstacles.Add(new(11*64,10*64,64,64));Check(!HorseFeature.CheckSafe(w.Farm,w.HA,p),"wide footprint object collision");w.Farm.Obstacles.Clear();w.B.Position=p;Check(!HorseFeature.CheckSafe(w.Farm,w.HA,p),"player collision");w.B.Position=new(50*64,50*64);var npc=new NPC{Position=p};w.Farm.characters.Add(npc);Check(!HorseFeature.CheckSafe(w.Farm,w.HA,p),"NPC collision");w.Farm.characters.Remove(npc);w.Farm.Map.GetLayer("Back")!.Tiles[10,10]=null;Check(!HorseFeature.CheckSafe(w.Farm,w.HA,p),"void tile");Check(!HorseFeature.CheckSafe(w.Farm,w.HA,new(-64,0)),"bounds");});
  Case("dynamic obstacle stops and replans without tunneling",()=>{var w=new World();w.Mod.Handle(w.Request(w.A,w.HA));w.Mod.MovementStep();var start=w.HA.Position;w.Farm.Obstacles.Add(new((int)start.X+112,(int)start.Y,64,64));for(int i=0;i<12;i++){w.Mod.MovementStep();Check(HorseFeature.CheckSafe(w.Farm,w.HA,w.HA.Position),"never entered obstacle");}w.Mod.Replan();w.Run();Check(w.Mod.Running==0&&Vector2.Distance(w.HA.Position,w.A.Position)<330,"rerouted around obstruction");Check(Game1.Warps.Count==0,"no visible reposition during reroute");});
  Case("map change, disconnect, saving and demolition clear active state",()=>{foreach(string scenario in new[]{"map","disconnect","save","demolish"}){var w=new World();w.Mod.Handle(w.Request(w.A,w.HA));w.Mod.MovementStep();if(scenario=="map"){w.Cross();w.Mod.MovementStep();}else if(scenario=="disconnect"){Game1.Offline.Add(101);w.Helper.Events.Multiplayer.Disconnect(101);}else if(scenario=="save")w.Helper.Events.GameLoop.Save();else{w.Farm.buildings.Remove(w.SA);w.Farm.characters.Remove(w.HA);w.Helper.Events.World.Remove(w.SA);}Check(w.Mod.Running==0&&!w.HA.modData.ContainsKey(HorseFeature.RunningKey)&&!w.HA.Frozen,scenario+" cleanup");Check(w.SA.owner.Value==101,scenario+" does not release ownership");if(scenario=="demolish")Check(!w.A.modData.ContainsKey(HorseFeature.SelectedNameKey),"selection cleaned");}});
  Case("stable move/reload preserves native owner/GUID and independent names",()=>{var w=new World();HorseFeature.Recovery(w.SA);Guid id=w.SA.HorseId;w.Farm.buildings.Remove(w.SA);w.SA.Parent=w.Town;w.Town.buildings.Add(w.SA);w.Helper.Events.GameLoop.Load();Check(w.SA.owner.Value==101&&w.SA.HorseId==id&&w.HA.Name=="Maple","stable move stable identity");Check(!w.HA.modData.ContainsKey(HorseFeature.RunningKey),"load clears transient movement");var data=JsonSerializer.Deserialize<Dictionary<string,string>>(JsonSerializer.Serialize(w.SA.modData))!;Check(data[HorseFeature.PersistentNameKey]=="Maple","persisted metadata boundary roundtrip");});
  Case("network rejects forged identity and accepts authenticated farmhand call",()=>{var w=new World();var forged=w.Request(w.A,w.HA);w.Helper.Events.Multiplayer.Receive(new(){FromPlayerID=202,Type="BSV.Horse.Request.v1",Body=forged});w.Helper.Events.GameLoop.Tick();Check(w.Mod.Running==0,"sender mismatch");var real=w.Request(w.B,w.HB);w.Helper.Events.Multiplayer.Receive(new(){FromPlayerID=202,Type="BSV.Horse.Request.v1",Body=real});w.Helper.Events.GameLoop.Tick();Check(w.Mod.Running==1&&w.Mod.Last(202)?.Running==true,"farmhand call authorized");Check(w.Helper.Multiplayer.Sent.Any(s=>s.Type=="BSV.Horse.Receipt.v1"&&s.Targets!.Contains(202)),"receipt targets actual caller");});
  Case("client requests do not mutate horse position; host required",()=>{var w=new World();Context.IsMainPlayer=false;Game1.player=w.B;Game1.viewport=new(2560,1360,640,480);w.Helper.Multiplayer.Peers[101]=new();w.Helper.Events.Input.Raise(SButton.H);Check(w.Mod.Running==0&&Game1.Warps.Count==0,"client never moves world");Check(w.Helper.Multiplayer.Sent.Any(s=>s.Type=="BSV.Horse.Request.v1"),"client sends request");w.Mod.ResetInput();w.Helper.Multiplayer.Peers.Clear();Game1.Trace.Clear();w.Helper.Events.Input.Raise(SButton.H);Check(Game1.Trace.Last()=="Message:horse.call.host_required","missing host mod explicit");Context.IsMainPlayer=true;});
  Case("split-screen local inbox queues for main-screen authority",()=>{var w=new World();Context.IsSplitScreen=true;Context.ScreenId=1;Context.IsMainPlayer=false;Game1.player=w.B;Game1.viewport=new(2560,1360,640,480);w.Helper.Events.Input.Raise(SButton.H);Check(w.Mod.Running==0,"secondary screen queues only");Context.ScreenId=0;Context.IsMainPlayer=true;Game1.player=w.A;Game1.viewport=new(1280,1360,640,480);w.Helper.Events.GameLoop.Tick();Check(w.Mod.Running==1&&w.Mod.Last(202)?.Running==true,"main screen processes local request");Context.IsSplitScreen=false;});
  Case("actual native frame selection; empty saddle; UI proximity/disable",()=>{var w=new World();w.HA.modData[HorseFeature.RunningKey]="run";HorseFeature.Animate(w.HA);foreach(int facing in new[]{0,1,2,3}){w.HA.faceDirection(facing);var seen=new HashSet<int>();for(int n=0;n<6;n++){w.HA.Position+=new Vector2(4,0);HorseFeature.Animate(w.HA);seen.Add(w.HA.Sprite.CurrentFrame);Check(w.HA.rider==null,"no rider for frames");}Check(seen.SetEquals(Enumerable.Range(facing==0?15:facing==2?1:8,6)),"all six native frames per direction");}var draw=new RenderedWorldEventArgs();w.Helper.Events.Display.Draw(draw);Check(draw.SpriteBatch.Draws==0,"far labels hidden");w.HA.Position=w.A.Position+new Vector2(128,0);w.Helper.Events.Display.Draw(draw);Check(draw.SpriteBatch.Draws==2,"near original-style background shown");w.Config.EnableHorseNameUI=false;w.Helper.Events.Display.Draw(draw);Check(draw.SpriteBatch.Draws==2,"UI disable");});
  Case("replicated completion keeps running frames through native interpolation",()=>{var w=new World();w.HA.modData[HorseFeature.RunningKey]="active";HorseFeature.Animate(w.HA);w.HA.modData.Remove(HorseFeature.RunningKey);w.HA.position.Interpolating=true;w.HA.Position+=new Vector2(4,0);HorseFeature.Animate(w.HA);Check(w.HA.Sprite.CurrentFrame>=8&&w.HA.Sprite.CurrentFrame<=13,"run frames during network tail");w.HA.position.Interpolating=false;HorseFeature.Animate(w.HA);Check(w.HA.Sprite.CurrentFrame==7,"idle only after interpolation finishes");});
  Case("multiple owned horses require explicit selection; command can reselect",()=>{var w=new World();w.SB.owner.Value=w.HB.ownerId.Value=101;w.Helper.Events.Input.Raise(SButton.H);Check(w.Farm.Question!=null&&w.Mod.Running==0,"no global first-horse selection");w.Farm.Question!.Value.Callback(w.A,w.HB.HorseId.ToString("N"));Game1.activeClickableMenu=null;w.Helper.Events.GameLoop.Tick();Check(w.Mod.Running==1&&w.A.modData[HorseFeature.SelectedNameKey]==w.HB.HorseId.ToString("N"),"chosen horse recorded by host");w.Helper.Events.GameLoop.Save();w.Mod.ResetInput();w.Helper.ConsoleCommands.Items["bsv_horse_choose"]("",Array.Empty<string>());Check(w.Farm.Question!.Value.Responses.Any(r=>r.responseKey==w.HA.HorseId.ToString("N")),"reselection menu offers other own horse");});
  Case("cooldown/replay and viewport validation rules",()=>{var g=new HorseRequestGate();Check(g.Accept(1,"a",0,5),"first");Check(!g.Accept(1,"b",4,5),"cooldown");Check(g.Accept(2,"a",1,5),"independent actor");Check(g.Accept(1,"b",5,5),"after cooldown");Check(!g.Accept(1,"a",20,5),"old replay after newer request");Check(!HorseRules.ValidEnvelope(1,2,Guid.NewGuid().ToString(),Guid.NewGuid().ToString(),"Town"),"forged actor");Check(HorseRules.ValidViewport(new(0,0,640,480),100,100),"real viewport");Check(!HorseRules.ValidViewport(new(99999,99999,640,480),100,100),"camera away from farmer");Check(!HorseRules.ValidViewport(new(0,0,int.MaxValue,480),100,100),"overflow dimensions");Check(HorseRules.StopRadii(3).SequenceEqual(new[]{3,2,4,5}),"parking fallback order");Check(HorseRules.CleanName(" [123]^\n Maple ")=="123 Maple","safe name");});
  Case("bounded path solver property checks on randomized obstructed maps",()=>{var random=new Random(947);int found=0;for(int run=0;run<60;run++){var blocks=new HashSet<Tile>();for(int x=0;x<24;x++)for(int y=0;y<20;y++)if(random.NextDouble()<.23)blocks.Add(new(x,y));Tile start=new(1,1),end=new(22,18);blocks.Remove(start);blocks.Remove(end);var path=HorseRules.Route(new[]{end},t=>t==start,t=>!blocks.Contains(t),(a,b)=>true,24,20,run);if(path==null)continue;found++;Check(path[0]==start&&path[^1]==end,"path endpoints");for(int i=0;i<path.Count;i++){Check(!blocks.Contains(path[i])&&path[i].X>=0&&path[i].X<24&&path[i].Y>=0&&path[i].Y<20,"only safe in-bounds cells");if(i>0)Check(Math.Abs(path[i].X-path[i-1].X)+Math.Abs(path[i].Y-path[i-1].Y)==1,"no diagonal wall cutting");}}Check(found>20,"meaningful reachable cases");});
  Case("default H and explicit legacy J are preserved without UI2 switching",()=>{var w=new World();Check(w.Config.CallHorseKey==SButton.H,"default remains H");w.Helper.Events.Input.Raise(SButton.H);Check(Game1.Trace.Contains("Whistle"),"H reaches horse input");w=new World();w.Config.CallHorseKey=SButton.J;w.Helper.Events.Input.Raise(SButton.H);Check(w.Helper.Input.Suppressed==0&&w.Mod.Running==0,"custom J does not silently become H");w.Helper.Events.Input.Raise(SButton.J);Check(w.Helper.Input.Suppressed==1&&Game1.Trace.Contains("Whistle"),"explicit J reaches horse input");});
  Case("already-suppressed input and explicit None cannot call a horse",()=>{var w=new World();w.Helper.Input.AlreadySuppressed=true;w.Helper.Events.Input.Raise(SButton.H);Check(w.Helper.Input.Suppressed==0&&w.Mod.Running==0,"suppression respected");w.Helper.Input.AlreadySuppressed=false;w.Config.CallHorseKey=SButton.None;w.Helper.Events.Input.Raise(SButton.H);Check(w.Helper.Input.Suppressed==0&&w.Mod.Running==0,"explicit None disables horse input");});
  Case("permanent mounted speed, no trigger and no on-foot change",()=>{
   var w=new World();var method=typeof(HorseFeature).GetMethod("AfterMovementSpeed",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!;
   foreach(bool client in new[]{false,true})foreach(float original in new[]{0f,4f,7.07f,10f,20f})foreach(bool mounted in new[]{false,true}){
    Context.IsMainPlayer=!client;w.A.mount=mounted?w.HA:null;object[] args={w.A,original};method.Invoke(null,args);
    Check(Math.Abs((float)args[1]-original*(mounted?1.2f:1))<.0001,"native speed x1.2 only on horse, independent of host/client or buffs");
   }Context.IsMainPlayer=true;
  });
  TractorCases();
  Console.WriteLine(JsonSerializer.Serialize(new{suite="Horse production adapter + rules",assertions=checks,passed=true,scenarios,limitations="Headless API boundary doubles; no live Stardew Valley session, rendered gameplay or real multiplayer transport was available."},new JsonSerializerOptions{WriteIndented=true}));
 }
